UPDATE `interview` SET `saved_sheet` = json_object('layout', json('{"blocks":[{"kind":"identity"},{"kind":"biography"},{"kind":"sheet-nickname"},{"kind":"sheet-occupation"},{"kind":"sheet-interests"},{"kind":"sheet-area"},{"kind":"sheet-message"},{"kind":"social-links"},{"kind":"joined"},{"kind":"actions"}]}'), 'sheet', json(`saved_sheet`)) WHERE `saved_sheet` IS NOT NULL AND json_type(`saved_sheet`, '$.layout') IS NULL;
